-- ═══════════════════════════════════════════════════
-- 2. INSERT program_modes (базовые: free_chat + author_chat)
-- ═══════════════════════════════════════════════════

INSERT INTO program_modes (program_id, mode_template_id, enabled, sort_order, access_type, color_class, welcome_mode_label, welcome_title, welcome_subtitle, welcome_ai_message, welcome_replies, config)
SELECT
  p.id,
  mt.id,
  true,
  CASE
    WHEN mt.key = 'free_chat'    THEN 90
    WHEN mt.key = 'author_chat'  THEN 100
    ELSE mt.default_sort_order
  END,
  CASE
    WHEN mt.key = 'free_chat' THEN 'free'
    ELSE 'paid'
  END,
  'accent',
  CASE
    WHEN mt.key = 'free_chat'    THEN 'Свободный чат'
    WHEN mt.key = 'author_chat'  THEN 'Разговор с автором'
  END,
  CASE
    WHEN mt.key = 'free_chat'    THEN 'Просто поговорить'
    WHEN mt.key = 'author_chat'  THEN 'Спросить Ильяхова'
  END,
  CASE
    WHEN mt.key = 'free_chat'    THEN 'Любой вопрос по тексту, редактуре, инфостилю'
    WHEN mt.key = 'author_chat'  THEN 'AI в стиле Максима Ильяхова из видео-курса'
  END,
  CASE
    WHEN mt.key = 'free_chat' THEN
      E'Здесь можно спросить о чём угодно, что касается текста.\n\nПринеси кусок своего письма, поста, статьи или объявления — разберём по пирамиде Ильяхова: что не работает, где главная проблема, как переписать.\n\nЧто ты получишь:\n• Разбор конкретного текста по принципам инфостиля\n• Объяснение приёмов на твоих примерах\n• Альтернативные формулировки'
    WHEN mt.key = 'author_chat' THEN
      E'Спроси Максима. Принеси конкретный текст, ситуацию или вопрос.\n\nКак это работает: AI отвечает в стиле Ильяхова из видео-курса «Базовый курс сильного текста» — разговорно, прямо, с шутками. Без академического пафоса и «искренне ваш».\n\nЧто ты получишь:\n• Прямой разбор без лести\n• Конкретные приёмы в авторском голосе\n• Объяснение через бытовые примеры'
  END,
  CASE
    WHEN mt.key = 'free_chat' THEN
      '[
        {"text":"Хочу разобрать свой текст", "type":"normal"},
        {"text":"Не понимаю, как сформулировать главное", "type":"normal"},
        {"text":"Как написать сильный заголовок?", "type":"normal"},
        {"text":"Мне сложно сформулировать", "type":"exit"}
      ]'::jsonb
    WHEN mt.key = 'author_chat' THEN
      '[
        {"text":"Как мне сократить текст без потери смысла?", "type":"normal"},
        {"text":"Что такое информационный стиль?", "type":"normal"},
        {"text":"Покажи на моём письме что не так", "type":"normal"},
        {"text":"Расскажи что-то важное", "type":"exit"}
      ]'::jsonb
  END,
  '{}'::jsonb
FROM programs p
CROSS JOIN mode_templates mt
WHERE p.slug = 'pishi-sokraschay'
  AND mt.key IN ('free_chat', 'author_chat')
ON CONFLICT DO NOTHING;

